namespace sv_3bd3f0c7834b49cca9282996ee045b62.Services;

/// <summary>
/// Holds the currently selected warehouse for a single user circuit.
/// Registered as Scoped so each Blazor Server circuit gets its own instance.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_3bd3f0c7834b49cca9282996ee045b62.Services;

/// <summary>
/// Provides low-stock alert counts and notifies all subscribed components
/// when new data arrives.  Scoped per circuit for user isolation.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public int LastKnownCount { get; private set; }

    /// <summary>
    /// Fired after new alert data has been fetched so every subscriber
    /// (sidebar badge, dashboard panel, etc.) can re-render.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    /// <summary>Simulates a database query returning low-stock item count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        int count = _random.Next(0, 16); // 0–15
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches fresh data and broadcasts to all subscribers.
    /// Called by the polling component; consumers just listen to the event.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        LastKnownCount = await GetLowStockCountAsync(warehouseId);
        if (OnAlertDataChanged is not null)
            await OnAlertDataChanged.Invoke();
    }
}

