@* Interactive island embedded in the static MainLayout *@
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@using sv_3bd3f0c7834b49cca9282996ee045b62.Services

<div class="warehouse-selector">
    <label class="form-label text-white mb-1 small">Current Warehouse</label>
    <select class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }
}

@* Displays the low-stock alert count. Subscribes to InventoryAlertService
   so it updates whenever ANY component triggers a refresh. *@
@rendermode InteractiveServer
@implements IDisposable
@inject InventoryAlertService AlertService
@using sv_3bd3f0c7834b49cca9282996ee045b62.Services

@if (_count > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@_count</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-auto">0</span>
}

@code {
    private int _count;

    protected override void OnInitialized()
    {
        _count = AlertService.LastKnownCount;
        AlertService.OnAlertDataChanged += OnDataChanged;
    }

    private async Task OnDataChanged()
    {
        _count = AlertService.LastKnownCount;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= OnDataChanged;
    }
}

