@page "/dashboard"
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@using sv_3bd3f0c7834b49cca9282996ee045b62.Services

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Selected Warehouse</h5>
        <p class="card-text fs-4">
            <strong>@WarehouseState.CurrentWarehouseName</strong>
            <span class="text-muted small">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        @if (_alertCount.HasValue)
        {
            <p class="card-text fs-4">
                @if (_alertCount.Value > 0)
                {
                    <span class="badge bg-danger fs-5">@_alertCount.Value items below minimum</span>
                }
                else
                {
                    <span class="badge bg-success fs-5">All stock levels OK</span>
                }
            </p>
            <p class="text-muted small">Refreshes every 10 seconds &bull; Last update: @_lastRefresh?.ToString("HH:mm:ss")</p>
        }
        else
        {
            <p class="text-muted">Loading alert data&hellip;</p>
        }
    </div>
</div>

@code {
    private int? _alertCount;
    private DateTime? _lastRefresh;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Kick off the first poll immediately, then start the timer.
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            StartPolling();
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _ = PollLoop(_cts.Token);
    }

    private async Task PollLoop(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task OnAlertDataChanged()
    {
        _alertCount = AlertService.LastKnownCount;
        _lastRefresh = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the newly selected warehouse.
        StartPolling();
        InvokeAsync(async () =>
        {
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        });
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
    }
}

